jinja_yaml_template:
alias: "{{ automation_title }}"
description: "Керування витяжкою за вологістю."
mode: restart
trigger:
  - platform: numeric_state
    entity_id: {{ humidity_sensor }}
    above: {{ humidity_threshold }}
action:
  - service: "{{ 'fan.turn_on' if 'fan.' in exhaust_fan else 'switch.turn_on' }}"
    target:
      entity_id: {{ exhaust_fan }}
  - wait_for_trigger:
      - platform: numeric_state
        entity_id: {{ humidity_sensor }}
        below: {{ humidity_threshold - 5 }}
  - delay:
      minutes: {{ run_minutes }}
  - service: "{{ 'fan.turn_off' if 'fan.' in exhaust_fan else 'switch.turn_off' }}"
    target:
      entity_id: {{ exhaust_fan }}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Автоматична витяжка у ванній"
  {% endif %}

alias: "{{ automation_title }}"
description: "Сповіщення про високий рівень CO2."
mode: single
trigger:
  - platform: numeric_state
    entity_id: {{ co2_sensor }}
    above: {{ co2_threshold }}
action:
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "🌬️ Увага! Рівень CO2 перевищив норму ({% raw %}{{ states('{{ co2_sensor }}') }}{% endraw %} ppm). Рекомендується провітрити приміщення."

  {% endif %}

alias: "{{ automation_title }}"
description: "Термостат із cooldown."
mode: single
trigger:
  - platform: numeric_state
    entity_id: {{ temp_sensor }}
    below: {{ target_temp - 0.5 }}
    for:
      minutes: {{ cooldown_minutes }}
    id: "too_cold"
  - platform: numeric_state
    entity_id: {{ temp_sensor }}
    above: {{ target_temp + 0.5 }}
    for:
      minutes: {{ cooldown_minutes }}
    id: "too_hot"
action:
  - choose:
      - conditions:
          - condition: trigger
            id: "too_cold"
        sequence:
          - service: switch.turn_on
            target:
              entity_id: {{ heater_switch }}
      - conditions:
          - condition: trigger
            id: "too_hot"
        sequence:
          - service: switch.turn_off
            target:
              entity_id: {{ heater_switch }}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Розумний термостат із захистом реле (Cooldown)"
  {% endif %}

alias: "{{ automation_title }}"
description: "Капельний полив за розкладом із перевіркою рівня води."
mode: single
trigger:
  - platform: time
    at: "{{ schedule_time }}"
condition:
  - condition: state
    entity_id: {{ water_level_sensor }}
    state: "on"
action:
  {% if enable_telegram and telegram_notify_service %}
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "🌱 Капельний полив розпочато ({{ duration_minutes }} хв)."
  {% endif %}
  {% endif %}
  - service: switch.turn_on
    target:
      entity_id: {{ pump_switch }}
  - delay:
      minutes: {{ duration_minutes }}
  - service: switch.turn_off
    target:
      entity_id: {{ pump_switch }}
  {% if enable_telegram and telegram_notify_service %}
  - service: {{ telegram_notify_service }}
    data:
      message: "✅ Капельний полив завершено."
  {% endif %}
max_exceeded: silent

alias: "{{ automation_title }}"
description: "Економія енергії, коли нікого немає вдома."
mode: single
trigger:
  - platform: state
    entity_id: {{ presence_sensor }}
    to: "not_home"
    for:
      minutes: 10
action:
  - service: "{{ 'light.turn_off' if 'light.' in non_critical_switch else 'switch.turn_off' }}"
    target:
      entity_id: {{ non_critical_switch }}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Економія енергії (Нікого немає вдома)"
  {% endif %}

alias: "{{ automation_title }}"
description: "Сповіщення про низький заряд акумулятора."
mode: single
trigger:
  - platform: numeric_state
    entity_id: {{ battery_sensor }}
    below: {{ threshold }}
action:
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "⚠️ УВАГА! Заряд батареї впав нижче {{ threshold }}%!"

  {% endif %}

alias: "{{ automation_title }}"
description: "Моніторинг стану мережі та відправка сповіщень."
mode: single
trigger:
  - platform: state
    entity_id: {{ grid_status_sensor }}
action:
  - choose:
      - conditions:
          - condition: state
            entity_id: {{ grid_status_sensor }}
            state: "off"
        sequence:
          - delay: '00:00:01'
          {% if enable_telegram %}
          - service: {{ telegram_notify_service }}
            data:
              message: "🚨 Блекаут! Електропостачання вимкнено. {% if ups_battery_sensor %}Заряд батареї: {{ '{{' }} states('{{ ups_battery_sensor }}') {{ '}}' }}%{% endif %}"
          {% endif %}
      - conditions:
          - condition: state
            entity_id: {{ grid_status_sensor }}
            state: "on"
        sequence:
          - delay: '00:00:01'
          {% if enable_telegram %}
          - service: {{ telegram_notify_service }}
            data:
              message: "💡 Світло з'явилося! Електропостачання відновлено."
          {% endif %}

alias: "{{ automation_title }}"
description: "Автоматичне вимкнення потужних приладів при роботі від інвертора."
mode: single
trigger:
  - platform: state
    entity_id: {{ inverter_sensor }}
    to: "on"
action:
  - service: switch.turn_off
    target:
      entity_id: {{ heavy_load_1 }}
  {% if heavy_load_2 %}
  - service: switch.turn_off
    target:
      entity_id: {{ heavy_load_2 }}
  {% endif %}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Авто-вимкнення приладів при роботі від інвертора"
  {% endif %}

alias: "{{ automation_title }}"
description: "Перемикання інвертора на мережу при низькому сонці."
mode: single
trigger:
  - platform: numeric_state
    entity_id: {{ solar_power_sensor }}
    below: {{ power_threshold }}
    for:
      minutes: 10
action:
  - service: select.select_option
    target:
      entity_id: {{ inverter_mode_select }}
    data:
      option: "{{ grid_mode_option }}"

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Контроль генератора / сонячного інвертора"
  {% endif %}

alias: "{{ automation_title }}"
description: "Peak shaving: вимкнення приладу при перевищенні ліміту потужності."
mode: single
trigger:
  - platform: numeric_state
    entity_id: {{ total_power_sensor }}
    above: {{ power_limit }}
    for:
      seconds: 30
action:
  - service: switch.turn_off
    target:
      entity_id: {{ heavy_load_switch }}
  {% if telegram_notify_service %}
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "⚡ Перевищено ліміт потужності ({{ power_limit }}Вт). Вимкнено потужний прилад для балансування."
  {% endif %}

  {% endif %}

alias: "{{ automation_title }}"
description: "Дозування добрив порціями із захистом від повторного запуску."
mode: single
trigger:
  - platform: state
    entity_id: {{ trigger_entity }}
    to: "on"
condition:
  - condition: template
    value_template: "{% raw %}{{ (as_timestamp(now()) - as_timestamp(state_attr('automation.{% endraw %}{{ automation_title | lower | replace(' ', '_') }}{% raw %}', 'last_triggered') | default(0))) > ({% endraw %}{{ cooldown_hours }}{% raw %} * 3600) }}{% endraw %}"
action:
  {% if enable_telegram and telegram_notify_service %}
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "🧪 Дозування добрив розпочато ({{ portions }} порцій по {{ dose_seconds }} сек)."
  {% endif %}
  {% endif %}
  - repeat:
      count: {{ portions }}
      sequence:
        - service: switch.turn_on
          target:
            entity_id: {{ dosing_pump }}
        - delay:
            seconds: {{ dose_seconds }}
        - service: switch.turn_off
          target:
            entity_id: {{ dosing_pump }}
        {% if portions > 1 %}
        - delay:
            seconds: {{ pause_between_seconds }}
        {% endif %}
  - service: switch.turn_off
    target:
      entity_id: {{ dosing_pump }}
  {% if enable_telegram and telegram_notify_service %}
  - service: {{ telegram_notify_service }}
    data:
      message: "✅ Дозування добрив завершено ({{ portions }} порцій)."
  {% endif %}
max_exceeded: silent

alias: "Greenhouse Climate Master"
description: "Автоматичне управління вентиляцією та зволоженням."
mode: queued
trigger:
  - platform: state
    entity_id: {{ temp_sensor }}
  - platform: state
    entity_id: {{ humidity_sensor }}
action:
  - choose:
      - conditions:
          - condition: numeric_state
            entity_id: {{ temp_sensor }}
            above: {{ target_temp + temp_hysteresis }}
        sequence:
          - service: "{{ 'cover.open_cover' if 'cover.' in window_actuator else 'switch.turn_on' }}"
            target:
              entity_id: {{ window_actuator }}
          {% if enable_telegram and telegram_target %}
          - service: {{ telegram_target }}
            data:
              message: "🌡️ Температура вище норми. Відкриваю вентиляцію."
          {% endif %}
      - conditions:
          - condition: numeric_state
            entity_id: {{ temp_sensor }}
            below: {{ target_temp - temp_hysteresis }}
        sequence:
          - service: "{{ 'cover.close_cover' if 'cover.' in window_actuator else 'switch.turn_off' }}"
            target:
              entity_id: {{ window_actuator }}
          {% if enable_telegram and telegram_target %}
          - service: {{ telegram_target }}
            data:
              message: "❄️ Температура нижче норми. Закриваю вентиляцію."
          {% endif %}
  - choose:
      - conditions:
          - condition: numeric_state
            entity_id: {{ humidity_sensor }}
            above: {{ target_humidity }}
        sequence:
          - service: switch.turn_on
            target:
              entity_id: {{ dehumidifier_switch }}
          {% if enable_telegram and telegram_target %}
          - service: {{ telegram_target }}
            data:
              message: "💧 Вологість вище норми. Вмикаю осушувач."
          {% endif %}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Комплексний клімат-контроль теплиці"
  {% endif %}

alias: "{{ automation_title }}"
description: "Щоденна промивка фільтрів води."
mode: single
trigger:
  - platform: time
    at: "{{ schedule_time }}"
action:
  - service: switch.turn_on
    target:
      entity_id: {{ flush_valve }}
  - delay:
      seconds: {{ flush_seconds }}
  - service: switch.turn_off
    target:
      entity_id: {{ flush_valve }}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Промивка фільтрів"
  {% endif %}

alias: "{{ automation_title }}"
description: "Полив при низькій вологості ґрунту."
mode: single
trigger:
  - platform: numeric_state
    entity_id: {{ soil_sensor }}
    below: {{ moisture_threshold }}
action:
  - service: switch.turn_on
    target:
      entity_id: {{ irrigation_valve }}
  - delay:
      minutes: {{ duration_minutes }}
  - service: switch.turn_off
    target:
      entity_id: {{ irrigation_valve }}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Полив за датчиком вологості ґрунту"
  {% endif %}

alias: "{{ automation_title }}"
description: "Дозування pH з лімітом циклів та паузою на перемішування."
mode: single
trigger:
  - platform: numeric_state
    entity_id: {{ ph_sensor }}
    above: {{ target_ph_max }}
action:
  {% if enable_telegram and telegram_notify_service %}
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "⚗️ pH вище норми ({% raw %}{{ states('{{ ph_sensor }}') }}{% endraw %}). Починаю дозування."
  {% endif %}
  {% endif %}
  - repeat:
      count: {{ max_cycles }}
      sequence:
        - service: switch.turn_on
          target:
            entity_id: {{ dosing_pump }}
        - delay:
            seconds: {{ dose_seconds }}
        - service: switch.turn_off
          target:
            entity_id: {{ dosing_pump }}
        - delay:
            seconds: {{ pause_seconds }}
        - condition: numeric_state
          entity_id: {{ ph_sensor }}
          above: {{ target_ph_max }}
  - service: switch.turn_off
    target:
      entity_id: {{ dosing_pump }}
  {% if enable_telegram and telegram_notify_service %}
  - service: {{ telegram_notify_service }}
    data:
      message: "✅ Дозування pH завершено. Поточний pH: {% raw %}{{ states('{{ ph_sensor }}') }}{% endraw %}."
  {% endif %}
max_exceeded: silent

alias: "{{ automation_title }}"
description: "Захист від протікання води (перекриття крана)."
mode: single
trigger:
  - platform: state
    entity_id: {{ leak_sensor }}
    to: "on"
action:
  - service: switch.turn_off
    target:
      entity_id: {{ water_valve }}
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "🚨 АВАРІЯ! Виявлено протікання води! Воду автоматично перекрито."

  {% endif %}

alias: "{{ automation_title }}"
description: "Увімкнення сирени при виявленні руху в режимі охорони."
mode: single
trigger:
  - platform: state
    entity_id: {{ motion_sensor }}
    to: "on"
condition:
  - condition: state
    entity_id: {{ alarm_panel }}
    state: "armed_away"
action:
  - service: alarm_control_panel.alarm_trigger
    target:
      entity_id: {{ alarm_panel }}
  - service: "{{ 'siren.turn_on' if 'siren.' in siren_switch else 'switch.turn_on' }}"
    target:
      entity_id: {{ siren_switch }}
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "🚨 ТРИВОГА! Виявлено рух під час охорони! Увімкнено сирену."

  {% endif %}

alias: "{{ automation_title }}"
description: "Авто-перекриття крана при протіканні."
mode: single
trigger:
  - platform: state
    entity_id: {{ leak_sensor }}
    to: "on"
action:
  - service: switch.turn_off
    target:
      entity_id: {{ water_valve }}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Захист від протікання"
  {% endif %}

alias: "{{ automation_title }}"
description: "Нічна підсвітка коридору."
mode: restart
trigger:
  - platform: state
    entity_id: {{ motion_sensor }}
    to: "on"
condition:
  - condition: time
    after: "{{ start_time }}"
    before: "{{ end_time }}"
action:
  - service: light.turn_on
    target:
      entity_id: {{ night_light }}
    data:
      brightness_pct: {{ brightness_pct }}
  - wait_for_trigger:
      - platform: state
        entity_id: {{ motion_sensor }}
        to: "off"
        for:
          minutes: {{ duration_minutes }}
  - service: light.turn_off
    target:
      entity_id: {{ night_light }}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Нічна підсвітка за рухом"
  {% endif %}

alias: "{{ automation_title }}"
description: "Попередження про відкрите вікно при увімкненому кліматі."
mode: single
trigger:
  - platform: state
    entity_id: {{ window_sensor }}
    to: "on"
    for:
      minutes: {{ timeout_minutes }}
condition:
  - condition: not
    conditions:
      - condition: state
        entity_id: {{ climate_entity }}
        state: "off"
action:
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "⚠️ УВАГА! Вікно відкрите більше {{ timeout_minutes }} хв, а клімат ({{ climate_entity }}) увімкнено! Закрийте вікно або вимкніть кондиціонер."

  {% endif %}

alias: "{{ automation_title }}"
description: "Імітація присутності вдома."
mode: restart
trigger:
  - platform: time
    at: "{{ start_time }}"
condition: []
action:
  - repeat:
      while:
        - condition: time
          before: "{{ end_time }}"
      sequence:
        - delay:
            minutes: "{% raw %}{{ range(10, 45) | random }}{% endraw %}"
        - service: "{{ 'light.toggle' if 'light.' in light_1 else 'switch.toggle' }}"
          target:
            entity_id: {{ light_1 }}
        {% if light_2 %}
        - delay:
            minutes: "{% raw %}{{ range(5, 20) | random }}{% endraw %}"
        - service: "{{ 'light.toggle' if 'light.' in light_2 else 'switch.toggle' }}"
          target:
            entity_id: {{ light_2 }}
        {% endif %}
  - service: "{{ 'light.turn_off' if 'light.' in light_1 else 'switch.turn_off' }}"
    target:
      entity_id: {{ light_1 }}
  {% if light_2 %}
  - service: "{{ 'light.turn_off' if 'light.' in light_2 else 'switch.turn_off' }}"
    target:
      entity_id: {{ light_2 }}
  {% endif %}

  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "Спрацювала автоматизація: Імітація присутності вдома"
  {% endif %}

alias: "{{ automation_title }}"
description: "Автоматичне наповнення бака з аварійним вимкненням за таймером."
mode: single
trigger:
  - platform: state
    entity_id: {{ low_level_sensor }}
    to: "on"
action:
  - service: switch.turn_on
    target:
      entity_id: {{ valve_switch }}
  {% if enable_telegram and telegram_notify_service %}
  {% if enable_telegram %}
  - service: {{ telegram_notify_service }}
    data:
      message: "🚰 Наповнення бака розпочато."
  {% endif %}
  {% endif %}
  - wait_for_trigger:
      - platform: state
        entity_id: {{ high_level_sensor }}
        to: "on"
    timeout:
      minutes: {{ max_run_minutes }}
    continue_on_timeout: true
  - service: switch.turn_off
    target:
      entity_id: {{ valve_switch }}
  {% if enable_telegram and telegram_notify_service %}
  - if:
      - condition: template
        value_template: "{% raw %}{{ wait.completed == false }}{% endraw %}"
    then:
      - service: {{ telegram_notify_service }}
        data:
          message: "⚠️ УВАГА! Наповнення бака зупинено за ТАЙМ-АУТОМ ({{ max_run_minutes }} хв)! Перевірте датчик або насос."
    else:
      - service: {{ telegram_notify_service }}
        data:
          message: "✅ Бак успішно наповнено."
  {% endif %}
